import { useId, useState } from "react";
import { Button } from "./button";
import { Input } from "./input";
import { NativeSelect } from "./native-select";
import { Tabs, TabsList, TabsTrigger } from "./tabs";
import {
    areWorkViewConfigsEqual,
    cloneWorkViewConfig,
} from "./work-view";
import type {
    SavedWorkView,
    WorkViewConfig,
    WorkViewPinnedColumns,
    WorkViewSort,
} from "./work-view";

type SavedViewCreateInput = {
    name: string;
    scope: "private" | "shared";
    config: WorkViewConfig;
    sourceViewId?: string;
};

type SavedViewBarPermissions = {
    canCreatePrivate?: boolean;
    canEditPrivate?: boolean;
    canDeletePrivate?: boolean;
    canReorderPrivate?: boolean;
    canCreateShared?: boolean;
    canEditShared?: boolean;
    canDeleteShared?: boolean;
    canReorderShared?: boolean;
    canChangeScope?: boolean;
};

type SavedViewBarProps = {
    views: readonly SavedWorkView[];
    selectedViewId: string | null;
    currentConfig: WorkViewConfig;
    permissions?: SavedViewBarPermissions;
    onSelectView: (id: string | null) => void;
    onCreateView?: (view: SavedViewCreateInput) => void | Promise<void>;
    onRenameView?: (id: string, name: string) => void | Promise<void>;
    onDuplicateView?: (view: SavedViewCreateInput) => void | Promise<void>;
    onReorderViews?: (ids: readonly string[]) => void | Promise<void>;
    onDeleteView?: (id: string) => void | Promise<void>;
    onChangeScope?: (
        id: string, scope: SavedWorkView["scope"],
    ) => void | Promise<void>;
    onSaveDraft: (id: string, config: WorkViewConfig) => void | Promise<void>;
    onCancelDraft: (id: string) => void;
    className?: string;
};

type ViewForm =
    | { kind: "create" }
    | { kind: "rename"; viewId: string }
    | { kind: "duplicate"; viewId: string };

function errorMessage(error: unknown) {
    return error instanceof Error && error.message.trim()
        ? error.message : "변경을 저장하지 못했습니다. 다시 시도하세요.";
}

function SavedViewBar({
    views, selectedViewId, currentConfig, permissions,
    onSelectView, onCreateView, onRenameView, onDuplicateView,
    onReorderViews, onDeleteView, onChangeScope, onSaveDraft,
    onCancelDraft, className,
}: SavedViewBarProps) {
    const id = useId();
    const selected = views.find((view) => view.id === selectedViewId);
    const dirty = selected !== undefined &&
        !areWorkViewConfigsEqual(selected.config, currentConfig);
    const [form, setForm] = useState<ViewForm | null>(null);
    const [name, setName] = useState("");
    const [scope, setScope] = useState<SavedWorkView["scope"]>("private");
    const [deleteConfirmation, setDeleteConfirmation] = useState<string | null>(
        null,
    );
    const [pending, setPending] = useState(false);
    const [message, setMessage] = useState<string | null>(null);

    const canCreatePrivate = permissions?.canCreatePrivate !== false;
    const canCreateShared = permissions?.canCreateShared === true;
    const canManageSelected = selected?.scope === "private"
        ? permissions?.canEditPrivate !== false : permissions?.canEditShared === true;
    const canDeleteSelected = selected?.scope === "private"
        ? permissions?.canDeletePrivate !== false : permissions?.canDeleteShared === true;
    const canReorderSelected = selected?.scope === "private"
        ? permissions?.canReorderPrivate !== false : permissions?.canReorderShared === true;
    const canChangeSelectedScope = permissions?.canChangeScope === true;
    const selectedIndex = views.findIndex((view) =>
        view.id === selectedViewId,
    );

    function canMoveSelected(direction: -1 | 1) {
        if (selectedIndex < 0) return false;
        const neighbor = views[selectedIndex + direction];
        if (!neighbor) return false;
        const crossesShared = selected?.scope === "shared" ||
            neighbor.scope === "shared";
        return !crossesShared || permissions?.canReorderShared === true;
    }

    function startCreate() {
        setForm({ kind: "create" });
        setName("");
        setScope(canCreatePrivate ? "private" : "shared");
        setMessage(null);
    }

    function startRename() {
        if (!selected) return;
        setForm({ kind: "rename", viewId: selected.id });
        setName(selected.name);
        setMessage(null);
    }

    function startDuplicate() {
        if (!selected) return;
        setForm({ kind: "duplicate", viewId: selected.id });
        setName(`${selected.name} 복사`);
        setScope(canCreatePrivate ? "private" : "shared");
        setMessage(null);
    }

    function closeForm() {
        setForm(null);
        setName("");
        setMessage(null);
    }

    function canSubmitCurrentForm() {
        if (!form || !name.trim() || pending) return false;
        if (form.kind === "rename") {
            const source = views.find((view) => view.id === form.viewId);
            if (!source || !onRenameView) return false;
            return source.scope === "private"
                ? permissions?.canEditPrivate !== false
                : permissions?.canEditShared === true;
        }
        const canCreateScope = scope === "private"
            ? canCreatePrivate : canCreateShared;
        if (!canCreateScope) return false;
        if (form.kind === "duplicate") {
            return Boolean(onDuplicateView && views.some((view) =>
                view.id === form.viewId,
            ));
        }
        return Boolean(onCreateView);
    }

    async function submitForm() {
        const cleanName = name.trim();
        if (!form || !cleanName || !canSubmitCurrentForm()) return;
        setPending(true);
        setMessage(null);
        try {
            if (form.kind === "rename") {
                await onRenameView?.(form.viewId, cleanName);
            } else if (form.kind === "duplicate") {
                const source = views.find((view) =>
                    view.id === form.viewId,
                );
                if (!source || !onDuplicateView) return;
                await onDuplicateView({
                    name: cleanName,
                    scope,
                    config: cloneWorkViewConfig(source.config),
                    sourceViewId: source.id,
                });
            } else {
                if (!onCreateView) return;
                await onCreateView({
                    name: cleanName,
                    scope,
                    config: cloneWorkViewConfig(currentConfig),
                });
            }
            closeForm();
        } catch (error) {
            setMessage(errorMessage(error));
        } finally {
            setPending(false);
        }
    }

    async function saveDraft() {
        if (!selected || !dirty || !canManageSelected || pending) return;
        setPending(true);
        setMessage(null);
        try {
            await onSaveDraft(selected.id, cloneWorkViewConfig(currentConfig));
        } catch (error) {
            setMessage(errorMessage(error));
        } finally {
            setPending(false);
        }
    }

    function cancelDraft() {
        if (!selected) return;
        onCancelDraft(selected.id);
        setMessage(null);
    }

    async function deleteSelected() {
        if (!selected || !onDeleteView || pending) return;
        setPending(true);
        setMessage(null);
        try {
            await onDeleteView(selected.id);
            setDeleteConfirmation(null);
            const next = views.find((view) => view.id !== selected.id);
            onSelectView(next?.id ?? null);
        } catch (error) {
            setMessage(errorMessage(error));
        } finally {
            setPending(false);
        }
    }

    async function changeScope(nextScope: SavedWorkView["scope"]) {
        if (!selected || !onChangeScope || !canChangeSelectedScope ||
            selected.scope === nextScope || pending) return;
        setPending(true);
        setMessage(null);
        try {
            await onChangeScope(selected.id, nextScope);
        } catch (error) {
            setMessage(errorMessage(error));
        } finally {
            setPending(false);
        }
    }

    async function moveSelected(direction: -1 | 1) {
        if (!selected || !onReorderViews || !canReorderSelected || pending) {
            return;
        }
        const index = views.findIndex((view) => view.id === selected.id);
        const nextIndex = index + direction;
        if (index < 0 || nextIndex < 0 || nextIndex >= views.length) return;
        const crossedShared = views[index].scope === "shared" ||
            views[nextIndex].scope === "shared";
        if (crossedShared && !permissions?.canReorderShared) return;
        const next = views.map((view) => view.id);
        [next[index], next[nextIndex]] = [next[nextIndex], next[index]];
        setPending(true);
        setMessage(null);
        try {
            await onReorderViews(next);
        } catch (error) {
            setMessage(errorMessage(error));
        } finally {
            setPending(false);
        }
    }

    const formCanSubmit = canSubmitCurrentForm();

    return (
        <section className={className} data-ui="saved-view-bar"
            aria-label="저장된 보기">
            <div className="flex min-w-0 flex-wrap items-center gap-2">
                {views.length > 0 && (
                    <Tabs value={selectedViewId ?? ""}
                        onValueChange={onSelectView}>
                        <TabsList variant="line" aria-label="보기 선택">
                            {views.map((view) => (
                                <TabsTrigger key={view.id} value={view.id}
                                    className="max-w-56">
                                    <span className="truncate">{view.name}</span>
                                    <span className="shrink-0 text-xs text-muted">
                                        {view.scope === "private" ? "개인" : "공유"}
                                    </span>
                                </TabsTrigger>
                            ))}
                        </TabsList>
                    </Tabs>
                )}
                {onCreateView && (canCreatePrivate || canCreateShared) && (
                    <Button variant="outline" onClick={startCreate}>
                        보기 추가
                    </Button>
                )}
            </div>

            {selected && (
                <div className="mt-2 flex min-w-0 flex-wrap items-center gap-2">
                    <span className="text-sm text-muted">
                        {selected.scope === "private" ? "개인 보기" : "공유 보기"}
                    </span>
                    {dirty && (
                        <span role="status" className="text-sm text-muted">
                            저장되지 않은 변경
                        </span>
                    )}
                    {dirty && canManageSelected && (
                        <Button variant="outline" disabled={pending}
                            onClick={saveDraft}>
                            변경 저장
                        </Button>
                    )}
                    {dirty && (
                        <Button variant="ghost" disabled={pending}
                            onClick={cancelDraft}>
                            취소
                        </Button>
                    )}
                    {onRenameView && canManageSelected && (
                        <Button variant="ghost" disabled={pending}
                            onClick={startRename}>
                            이름 변경
                        </Button>
                    )}
                    {onDuplicateView &&
                        (canCreatePrivate || canCreateShared) && (
                        <Button variant="ghost" disabled={pending}
                            onClick={startDuplicate}>
                            복제
                        </Button>
                    )}
                    {onReorderViews && canReorderSelected && (
                        <>
                            <Button variant="ghost" disabled={pending ||
                                !canMoveSelected(-1)}
                                aria-label={`${selected.name} 위로 이동`}
                                onClick={() => moveSelected(-1)}>
                                위로
                            </Button>
                            <Button variant="ghost" disabled={pending ||
                                !canMoveSelected(1)}
                                aria-label={`${selected.name} 아래로 이동`}
                                onClick={() => moveSelected(1)}>
                                아래로
                            </Button>
                        </>
                    )}
                    {onChangeScope && canChangeSelectedScope && (
                        <NativeSelect aria-label="보기 공유 범위"
                            disabled={pending}
                            value={selected.scope}
                            onChange={(event) => {
                                void changeScope(
                                    event.target.value as SavedWorkView["scope"],
                                );
                            }}>
                            <option value="private">개인</option>
                            <option value="shared">공유</option>
                        </NativeSelect>
                    )}
                    {onDeleteView && canDeleteSelected && (
                        deleteConfirmation === selected.id ? (
                            <span className="inline-flex flex-wrap items-center gap-2">
                                <span className="text-sm text-danger">
                                    이 보기를 삭제할까요?
                                </span>
                                <Button variant="outline" disabled={pending}
                                    onClick={() => void deleteSelected()}>
                                    삭제 확인
                                </Button>
                                <Button variant="ghost" disabled={pending}
                                    onClick={() => setDeleteConfirmation(null)}>
                                    삭제 취소
                                </Button>
                            </span>
                        ) : (
                            <Button variant="ghost" disabled={pending}
                                onClick={() =>
                                    setDeleteConfirmation(selected.id)}>
                                삭제
                            </Button>
                        )
                    )}
                </div>
            )}

            {form && (
                <div className={
                    "mt-3 grid max-w-xl gap-2 rounded-sm border " +
                    "border-border bg-surface-subtle p-[var(--space-3)]"
                }>
                    <label htmlFor={`${id}-name`} className="text-sm font-medium">
                        {form.kind === "rename" ? "보기 이름" : "새 보기 이름"}
                    </label>
                    <Input id={`${id}-name`} value={name}
                        maxLength={80}
                        onChange={(event) => setName(event.target.value)}
                        onKeyDown={(event) => {
                            if (event.nativeEvent.isComposing ||
                                event.nativeEvent.keyCode === 229 ||
                                event.key !== "Enter") return;
                            event.preventDefault();
                            void submitForm();
                        }} />
                    {form.kind !== "rename" && (
                        <label className="grid gap-1 text-sm">
                            <span>공유 범위</span>
                            <NativeSelect value={scope}
                                onChange={(event) => setScope(
                                    event.target.value as SavedWorkView["scope"],
                                )}>
                                {canCreatePrivate && (
                                    <option value="private">개인 보기</option>
                                )}
                                {canCreateShared && (
                                    <option value="shared">공유 보기</option>
                                )}
                            </NativeSelect>
                        </label>
                    )}
                    <div className="flex flex-wrap gap-2">
                        <Button variant="primary" disabled={!formCanSubmit}
                            onClick={() => void submitForm()}>
                            {form.kind === "rename" ? "이름 저장" : "보기 만들기"}
                        </Button>
                        <Button variant="ghost" disabled={pending}
                            onClick={closeForm}>
                            취소
                        </Button>
                    </div>
                </div>
            )}
            {message && <p role="alert" className="mt-2 text-sm text-danger">
                {message}
            </p>}
        </section>
    );
}

export { SavedViewBar };
export type {
    SavedViewBarPermissions,
    SavedViewBarProps,
    SavedViewCreateInput,
    SavedWorkView,
    WorkViewConfig,
    WorkViewPinnedColumns,
    WorkViewSort,
};
export { createWorkViewConfig } from "./work-view";
